// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCoupon, getCoupon } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // The duplicate check is only meaningful when the second request sends the
    // SAME code as the first, so the run-unique code is computed once and reused.
    const couponCode = uniqueSuffix("TESTBOT-DUP");

    const couponsPostResponse = await createCoupon(client, headers, couponCode, 10, 201);
    expect(couponsPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(couponsPostResponse, "response.code"), 'code').toBe(couponCode);
    expect(getResponseValue(couponsPostResponse, "response.discountPercent"), 'discountPercent').toBe(10);
    expect(getResponseValue(couponsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(couponsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const couponsPost1Response = await createCoupon(client, headers, couponCode, 50, 409);
    expect(couponsPost1Response.statusCode, 'status code').toBe(409);
    expect(getResponseValue(couponsPost1Response, "response"), 'conflict message').toBe("A coupon with this code already exists.");
    expect(getResponseValue(couponsPost1Response, "response.id"), 'no coupon is returned for the refused duplicate').toBeNull();
    expect(getResponseValue(couponsPost1Response, "response.discountPercent"), 'the refused duplicate creates no record').toBeNull();

    // The refusal must not have overwritten the original: it still carries the discount it was created with.
    const couponsCouponsGetResponse = await getCoupon(
        client,
        headers,
        getResponseValue(couponsPostResponse, "response.id")
    );
    expect(getResponseValue(couponsCouponsGetResponse, "response.discountPercent"), 'original discountPercent is unchanged').toBe(10);
    expect(getResponseValue(couponsCouponsGetResponse, "response.code"), 'original code is unchanged').toBe(couponCode);
});
